// `lib/src/bindings/flutter_soloud_ffigen.dart` is generated by ffigen from
// `src/bindings.h` (see ffigen.yaml). This checks that the committed file is
// still in sync with the header:
//
// - fast: every FFI_PLUGIN_EXPORT visible to ffigen (not behind
//   `__EMSCRIPTEN__` or `SOLOUD_LIFECYCLE_TEST_HOOKS`) has an `@ffi.Native`
//   binding with the same number of parameters, and nothing else is bound;
// - slow: ffigen is run into a temporary directory and its declarations are
//   compared with the committed ones. Ordering, formatting and output that
//   only depends on the ffigen version are ignored.
//
// The committed generated file is never written.
@TestOn('vm')
library;

import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:test/test.dart';

const _generatedPath = 'lib/src/bindings/flutter_soloud_ffigen.dart';
const _headerPath = 'src/bindings.h';

/// Macros that are undefined when ffigen parses the header on the host.
const _undefinedMacros = {'__EMSCRIPTEN__', 'SOLOUD_LIFECYCLE_TEST_HOOKS'};

/// The text of the file at [path] with `\n` line endings: git checks the
/// sources out with `\r\n` on Windows (core.autocrlf), and the line-based
/// parsers below would not recognize a directive followed by `\r`.
String _readText(String path) =>
    File(path).readAsStringSync().replaceAll('\r\n', '\n');

/// Removes `//` and `/* */` comments.
String _stripCComments(String s) => s
    .replaceAll(RegExp(r'/\*.*?\*/', dotAll: true), '')
    .replaceAll(RegExp('//.*'), '');

/// Splits the header into the code ffigen sees and the code it does not,
/// evaluating only `#if(n)def`/`#if defined()` on [_undefinedMacros]. Every
/// other condition (include guards, `__cplusplus`, `FFI_PLUGIN_EXPORT`) is
/// treated as taken, which is what matters for the exported declarations.
({String visible, String hidden}) _preprocess(String header) {
  final visible = StringBuffer();
  final hidden = StringBuffer();
  final stack = <bool>[];
  bool active() => stack.every((b) => b);

  bool? evaluate(String directive, String rest) {
    final macro = RegExp(
      r'\w+',
    ).firstMatch(rest.replaceFirst(RegExp(r'^\s*defined\s*\(?'), ''))?[0];
    if (macro == null || !_undefinedMacros.contains(macro)) return true;
    final negated =
        directive == 'ifndef' || RegExp(r'^\s*!\s*defined').hasMatch(rest);
    return negated;
  }

  for (final line in header.split('\n')) {
    final m = RegExp(r'^\s*#\s*(\w+)(.*)$').firstMatch(line);
    if (m != null) {
      final directive = m[1]!;
      final rest = m[2]!;
      switch (directive) {
        case 'if' || 'ifdef' || 'ifndef':
          stack.add(evaluate(directive, rest)!);
          continue;
        case 'else':
          stack.add(!stack.removeLast());
          continue;
        case 'endif':
          stack.removeLast();
          continue;
      }
    }
    (active() ? visible : hidden).writeln(line);
  }
  return (visible: visible.toString(), hidden: hidden.toString());
}

/// Number of top-level, comma-separated items in a C or Dart parameter list.
int _paramCount(String params) {
  final trimmed = params.trim();
  if (trimmed.isEmpty || trimmed == 'void') return 0;
  var depth = 0;
  var count = 1;
  for (final c in trimmed.split('')) {
    if ('(<[{'.contains(c)) depth++;
    if (')>]}'.contains(c)) depth--;
    if (c == ',' && depth == 0) count++;
  }
  // Dart allows a trailing comma.
  if (RegExp(r',\s*$').hasMatch(trimmed)) count--;
  return count;
}

/// `FFI_PLUGIN_EXPORT <ret> name(<params>);` -> name -> parameter count.
Map<String, int> _exports(String code) {
  final result = <String, int>{};
  final decl = RegExp(
    r'FFI_PLUGIN_EXPORT\b([^;{]*?)\b(\w+)\s*\(([^;{]*?)\)\s*[;{]',
    dotAll: true,
  );
  final withoutDirectives = _stripCComments(
    code,
  ).split('\n').where((l) => !l.trimLeft().startsWith('#')).join('\n');
  for (final m in decl.allMatches(withoutDirectives)) {
    result[m[2]!] = _paramCount(m[3]!);
  }
  return result;
}

/// Every `@ffi.Native` external function in the generated Dart: C symbol ->
/// parameter count.
Map<String, int> _bindings(String dart) {
  final result = <String, int>{};
  final code = dart
      .split('\n')
      .where((l) => !l.trimLeft().startsWith('//'))
      .join('\n');
  var index = 0;
  while ((index = code.indexOf('@ffi.Native<', index)) >= 0) {
    final external = code.indexOf('external ', index);
    final semicolon = code.indexOf(';', external);
    final annotation = code.substring(index, external);
    final declaration = code.substring(external, semicolon);
    final m = RegExp(
      r'(\w+)\s*\((.*)\)\s*$',
      dotAll: true,
    ).firstMatch(declaration);
    if (m == null) {
      fail('Unparsable binding: $declaration');
    }
    final symbol =
        RegExp(r"symbol:\s*'(\w+)'").firstMatch(annotation)?[1] ?? m[1]!;
    result[symbol] = _paramCount(m[2]!);
    index = semicolon;
  }
  return result;
}

/// Splits generated Dart into its top-level declarations, normalized so that
/// formatting and order do not matter. Version-specific ffigen output (the
/// `$allocate` struct helpers, block vs arrow bodies) is normalized away.
Set<String> _declarations(String dart) {
  final code = dart
      .split('\n')
      .where((l) => !l.trimLeft().startsWith('//'))
      .join('\n');
  final out = <String>{};
  final buffer = StringBuffer();
  var depth = 0;
  for (final c in code.split('')) {
    buffer.write(c);
    if ('({['.contains(c)) depth++;
    if (')}]'.contains(c)) depth--;
    if (depth == 0 && (c == ';' || c == '}')) {
      var s = buffer
          .toString()
          .replaceAll(RegExp(r'\s+'), ' ')
          .replaceAllMapped(RegExp(r'\s*([(){}\[\],;<>=])\s*'), (m) => m[1]!)
          .replaceAll(',)', ')')
          .replaceAll(',}', '}')
          .replaceAll(',>', '>')
          .trim();
      s = s
          .replaceAllMapped(
            RegExp(r'\)\{return (.*);\}$'),
            (m) => ')=>${m[1]};',
          )
          .replaceAll(
            RegExp(r'static ffi\.Pointer<\w+>\$allocate\(.*;\}$'),
            '}',
          )
          // Newer ffigen also emits a setter for enum-typed struct fields.
          .replaceAll(RegExp(r'set \w+\(\w+ value\)=>\w+=value\.value;'), '');
      if (s.isNotEmpty && !s.startsWith('import ') && s != 'library;') {
        out.add(s);
      }
      buffer.clear();
    }
  }
  return out;
}

void main() {
  final header = _readText(_headerPath);
  final generated = _readText(_generatedPath);

  group('generated bindings match the exports of src/bindings.h', () {
    final split = _preprocess(header);
    final exports = _exports(split.visible);
    final hidden = _exports(split.hidden);
    final bindings = _bindings(generated);

    test('the header parses', () {
      expect(exports.length, greaterThan(100));
      expect(hidden, isNotEmpty, reason: 'guarded exports exist');
    });

    test('every visible export has a binding', () {
      final missing = exports.keys.toSet().difference(bindings.keys.toSet());
      expect(
        missing,
        isEmpty,
        reason:
            'Exported in $_headerPath but not bound in $_generatedPath. '
            'Run `dart run ffigen --config ffigen.yaml`.',
      );
    });

    test('every binding is still exported', () {
      final stale = bindings.keys.toSet().difference(exports.keys.toSet());
      expect(
        stale,
        isEmpty,
        reason:
            'Bound in $_generatedPath but no longer exported (or now '
            'guarded) in $_headerPath. Regenerate the bindings.',
      );
    });

    test('guarded exports are not bound', () {
      expect(bindings.keys.toSet().intersection(hidden.keys.toSet()), isEmpty);
    });

    test('parameter counts match', () {
      final mismatches = <String>[
        for (final MapEntry(:key, :value) in exports.entries)
          if (bindings.containsKey(key) && bindings[key] != value)
            '$key: header $value, binding ${bindings[key]}',
      ];
      expect(mismatches, isEmpty);
    });
  });

  test(
    'regenerating with ffigen yields the committed declarations',
    tags: ['slow'],
    () async {
      final root = Directory.current.path;
      final temp = Directory.systemTemp.createTempSync('soloud_ffigen');
      addTearDown(() => temp.deleteSync(recursive: true));
      final output = p.join(temp.path, 'flutter_soloud_ffigen.dart');

      // Same config, absolute paths, output redirected to the temp dir.
      final config = File('ffigen.yaml')
          .readAsStringSync()
          .replaceFirst(RegExp("output: '[^']*'"), "output: '$output'")
          .replaceFirst(
            "- 'src/bindings.h'",
            "- '${p.join(root, _headerPath)}'",
          );
      expect(config, contains(output));
      final configFile = File(p.join(temp.path, 'ffigen.yaml'))
        ..writeAsStringSync(config);

      final flutterRoot = Platform.environment['FLUTTER_ROOT'];
      final dart = flutterRoot == null
          ? 'dart'
          : p.join(
              flutterRoot,
              'bin',
              Platform.isWindows ? 'dart.bat' : 'dart',
            );
      final before = File(_generatedPath).lastModifiedSync();

      final result = await Process.run(dart, [
        'run',
        'ffigen',
        '--config',
        configFile.path,
      ], workingDirectory: root);

      expect(
        File(_generatedPath).lastModifiedSync(),
        before,
        reason: 'the committed file must not be touched',
      );
      if (result.exitCode != 0 || !File(output).existsSync()) {
        final log = '${result.stdout}\n${result.stderr}';
        if (log.contains('libclang') || log.contains('Could not find')) {
          markTestSkipped('ffigen cannot run here (libclang): $log');
          return;
        }
        fail('ffigen failed (${result.exitCode}):\n$log');
      }

      final fresh = _declarations(_readText(output));
      final committed = _declarations(generated);
      String show(Set<String> s) => s
          .map((d) => d.length > 160 ? '${d.substring(0, 160)}...' : d)
          .join('\n');
      expect(
        show(fresh.difference(committed)),
        isEmpty,
        reason: 'Declarations ffigen generates but $_generatedPath lacks.',
      );
      expect(
        show(committed.difference(fresh)),
        isEmpty,
        reason: 'Declarations in $_generatedPath that ffigen no longer makes.',
      );
    },
  );
}
